function maxBoxesInWarehouse(boxes, warehouse) {
  boxes.sort((a, b) => b - a);
  let left = 0;
  let right = warehouse.length - 1;
  let count = 0;

  for (const box of boxes) {
    if (left > right) {
      break;
    }
    if (box <= warehouse[left]) {
      left++;
      count++;
    } else if (box <= warehouse[right]) {
      right--;
      count++;
    }
  }
  return count;
}

