function maxBoxesInWarehouse(boxes, warehouse) {
  // Simulate every push: any unused box, from either side, stopping in any room it can reach.
  const n = warehouse.length;
  const memo = new Map();
  const best = (occupied, used) => {
    const key = occupied * 256 + used;
    if (memo.has(key)) return memo.get(key);
    let result = 0;
    for (let b = 0; b < boxes.length; b++) {
      if ((used >> b) & 1) continue;
      for (const step of [1, -1]) {
        let j = step === 1 ? 0 : n - 1;
        while (j >= 0 && j < n && !((occupied >> j) & 1) && warehouse[j] >= boxes[b]) {
          result = Math.max(result, 1 + best(occupied | (1 << j), used | (1 << b)));
          j += step;
        }
      }
    }
    memo.set(key, result);
    return result;
  };
  return best(0, 0);
}

