function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const top = [2, 5, 9][int(0, 2)];
    const boxes = Array.from({ length: int(1, 6) }, () => int(1, top));
    const warehouse = Array.from({ length: int(1, 6) }, () => int(1, top));
    return [boxes, warehouse];
  }
  const BIG = 1000000000;
  const m = int(1500, 2000);
  const n = int(1500, 2000);
  const mode = int(0, 2);
  const boxes = Array.from({ length: m }, () => int(1, BIG));
  let warehouse;
  if (mode === 0) {
    warehouse = Array.from({ length: n }, () => int(1, BIG));
  } else {
    // A valley (high at both doors) or a ridge (low at both doors), with noise.
    const valley = mode === 1;
    warehouse = Array.from({ length: n }, (_, j) => {
      const edge = Math.abs(2 * j - (n - 1)) / (n - 1);
      const shape = valley ? edge : 0.2 + 0.8 * (1 - edge);
      return Math.min(BIG, Math.max(1, Math.floor(BIG * shape) - int(0, 30000000) + 1));
    });
  }
  return [boxes, warehouse];
}
